def a_modulos(apps, schema_editor):
    """La pantalla de cocina y el delivery pasan de ajustes a módulos; productos y ventas pasan a ser la base."""
    Ajustes = apps.get_model("core", "Ajustes")
    for a in Ajustes.objects.all():
        inactivos = [m for m in (a.modulos_inactivos or []) if m not in ("productos", "ventas")]
        if "ventas" in (a.modulos_inactivos or []):
            inactivos.append("mostrador")
        if not a.cocina_pantalla and "cocina" not in inactivos:
            inactivos.append("cocina")
        if not a.delivery_activo and "delivery" not in inactivos:
            inactivos.append("delivery")
        a.modulos_inactivos = inactivos
        a.save(update_fields=["modulos_inactivos"])


